// Chapter 2, first half cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch2a).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['brams-wagon', ["A memory, before anything bad happens", "Stew. Onions in whole", "The way I pretend to hate", "She reads it to him", "I'll take it in the morning", "He tucks it under the wagon seat"]],
    ['the-edge', ["The edge of the Cloud, the night after the wipe", "Somebody say it. We deleted her.", "You played the card, Kai.", "Because every one of you said", "Nobody said anything. Freya did.", "Enough. Sit down, all of you.", "Dutch tips Freya's gift basket out", "Same handwriting.", "Then we stop blaming each other"]],
    ['the-tower', ["At dawn they see it on the horizon", "Welcome to the Free Tier, everyone", "Everything's free. Great."]],
    ['the-scrap-field', ["At the tower's foot is the field", "Pingsby's post office. And someone in it.", "Pingsby kept versioning on", "Coo! Delivered!"]],
    ['the-bunker', ["In the middle of the field is a bunker", "Go away. I'm offline.", "I have one tape", "Then restore her.", "No. Two reasons", "Close the hatch"]],
    ['elder-wren', ["Elder Wren, whose faithful you beat"]],
    ['the-first-fire', ["That night, the first fire.", "We should call it something.", "Nobody here is on anyone's free tier", "The Free Cloud! I'll need letterhead."]],
    ['thornwick-square', ["Thornwick, rebuilt as the tower's first floor", "The bell-ringer pulls the rope", "Tilly walks the square", "Move along.", "Tilly..."]],
    ['the-post-box', ["Freya meets Mira at the silent post box", "Give me Thornwick's post, love"]],
    ['mira-doesnt-answer', ["Mira doesn't answer.", "Take your time. Everything here does."]],
    ['the-sorting-floors', ["Up the stair are the Sorting Floors"]],
    ['floors-grow-back', ["That night, from the camp, they watch", "Kyu's runbook, in her handwriting", "Excuse me. Sorry."]],
    ['shipped', ["Midnight. The tower redeploys from its template, and this time", "Floors 2 to 6 stay cleared", "Shipped! Delivered!"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
